insert into public.cards (id, name, family, type, tags, cost, power, toughness, speed, text, flavor, effects, wildcard, immune_to_suspend, art_character, art_action, art_prompt) values
  ('filtro-de-barro', 'Filtro de Barro', 'cozinha', 'objeto', '{}'::text[], 2, 0, 4, 1, 'Fim da rodada: cura 1 nas vizinhas. Com Vó na fileira: Tapetinho de Crochê, cura 2 e +2 Resistência.', 'Água de filtro de barro é outro nível. Todo mundo sabe.', '[{"trigger":"onRoundEnd","name":"Água fresquinha","actions":[{"kind":"heal","amount":1,"target":"neighbors"}]},{"trigger":"onRoundEnd","name":"Tapetinho de Crochê","conditions":[{"kind":"allyHasTag","tag":"vo"}],"actions":[{"kind":"heal","amount":1,"target":"neighbors"}]},{"trigger":"static","conditions":[{"kind":"allyHasTag","tag":"vo"}],"actions":[{"kind":"buff","toughness":2,"target":"self","duration":"round"}]}]'::jsonb, false, false, 'a chubby clay water filter with little arms and legs, a tiny tin cup hanging from its tap', 'proudly pouring water into a cup, chest puffed out, water drops sparkling, very satisfied smile', 'Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: fluorescent pink for the character, teal for the circle. Character: a chubby clay water filter with little arms and legs, a tiny tin cup hanging from its tap. Action: proudly pouring water into a cup, chest puffed out, water drops sparkling, very satisfied smile. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('vo', 'Vó', 'familia', 'pessoa', array['vo', 'parente']::text[], 3, 1, 5, 2, 'Parentesco: ao entrar, parentes vizinhos ganham +1/+1 nesta rodada.', 'Tá magrinho. Come mais um pouquinho.', '[{"trigger":"onEnter","name":"Parentesco","actions":[{"kind":"buff","power":1,"toughness":1,"target":{"tag":"parente","side":"ally","scope":"neighbors"},"duration":"round"}]}]'::jsonb, false, false, 'a tiny grandmother with round glasses, hair bun, floral dress and slippers, holding a crochet doily and knitting needles', 'offering a plate of food with a stern loving look that says you will eat all of it', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: brick red for the character, egg-yolk yellow for the radiating sunburst. Character: a tiny grandmother with round glasses, hair bun, floral dress and slippers, holding a crochet doily and knitting needles. Action: offering a plate of food with a stern loving look that says you will eat all of it. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('mae', 'Mãe', 'familia', 'pessoa', array['mae', 'parente']::text[], 4, 3, 5, 4, 'Quando um Filho entra na sua fileira: Chinelo Teleguiado, 3 de dano em inimigo aleatório. Ao entrar com 2+ jogadores de várzea na mesa: "Pra dentro, agora!", todos eles voltam para a mão.', 'Vou contar até três...', '[{"trigger":"onAllyEnter","name":"Chinelo Teleguiado","conditions":[{"kind":"enteringHasTag","tag":"filho"}],"actions":[{"kind":"damage","amount":3,"target":"randomEnemy"}]},{"trigger":"onEnter","name":"Pra dentro, agora!","conditions":[{"kind":"countTag","tag":"jogador","min":2,"side":"both"}],"actions":[{"kind":"returnToHand","target":{"tag":"jogador","side":"both"}}]}]'::jsonb, false, false, 'a mother in an apron with hair curlers, one hand on her hip', 'winding up to throw a flip-flop that has motion lines curving like a boomerang, eyes squinting with laser focus', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: brick red for the character, egg-yolk yellow for the radiating sunburst. Character: a mother in an apron with hair curlers, one hand on her hip. Action: winding up to throw a flip-flop that has motion lines curving like a boomerang, eyes squinting with laser focus. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('filho', 'Filho', 'familia', 'pessoa', array['filho', 'parente']::text[], 1, 1, 2, 3, 'Faz a Mãe jogar o chinelo.', 'Mãe, cadê meu tênis? Mãe? MÃE?', '[]'::jsonb, false, false, 'a skinny kid with messy hair, untied sneakers and a school backpack twice his size', 'running in with a guilty grin after breaking something off-screen, one sneaker flying off', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: brick red for the character, egg-yolk yellow for the radiating sunburst. Character: a skinny kid with messy hair, untied sneakers and a school backpack twice his size. Action: running in with a guilty grin after breaking something off-screen, one sneaker flying off. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('tio-do-pave', 'Tio do Pavê', 'familia', 'pessoa', array['parente']::text[], 3, 2, 3, 2, 'Com Sobremesa na fileira: "É pavê ou pra comer?" Inimigos à frente e vizinhos da frente perdem 1 Força.', 'Conta essa piada desde 1987. Ri sozinho desde 1987.', '[{"trigger":"static","name":"É pavê ou pra comer?","conditions":[{"kind":"allyHasTag","tag":"sobremesa"}],"actions":[{"kind":"buff","power":-1,"target":"enemyNeighborsOfSelf","duration":"round"}]}]'::jsonb, false, false, 'a mustached uncle in a loud printed shirt holding a big glass dish of layered dessert', 'pointing at the dessert and laughing at his own joke while the dessert itself rolls its eyes', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: brick red for the character, egg-yolk yellow for the radiating sunburst. Character: a mustached uncle in a loud printed shirt holding a big glass dish of layered dessert. Action: pointing at the dessert and laughing at his own joke while the dessert itself rolls its eyes. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('pudim', 'Pudim', 'cozinha', 'objeto', array['sobremesa']::text[], 1, 0, 3, 1, 'Fim da rodada: cura 1 em si mesmo.', 'Com furinho no meio, do jeito certo.', '[{"trigger":"onRoundEnd","name":"Calda","actions":[{"kind":"heal","amount":1,"target":"self"}]}]'::jsonb, false, false, 'a wobbly caramel flan with a hole in the middle, shiny syrup dripping down its sides, tiny legs', 'jiggling happily and waving, a drop of syrup landing on its own foot', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: fluorescent pink for the character, teal for the circle. Character: a wobbly caramel flan with a hole in the middle, shiny syrup dripping down its sides, tiny legs. Action: jiggling happily and waving, a drop of syrup landing on its own foot. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('mandrake', 'Mandrake', 'rua', 'pessoa', '{}'::text[], 3, 2, 3, 5, 'Ao entrar, se houver Moto na fileira: Grau! A Moto ganha +3 Pressa e ataca a Moral direto nesta rodada.', 'Grau é arte. Capacete é lei.', '[{"trigger":"onEnter","name":"Grau","conditions":[{"kind":"allyHasTag","tag":"moto"}],"actions":[{"kind":"buff","speed":3,"target":{"tag":"moto","side":"ally"},"duration":"round"},{"kind":"directAttack","target":{"tag":"moto","side":"ally"}}]}]'::jsonb, false, false, 'a stylish young guy with a flat-brim cap, sunglasses, chain necklace and a full-face helmet under his arm', 'posing confidently with two fingers up, one eyebrow raised, a small scooter behind him', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: traffic orange for the character, sky blue for the radiating sunburst. Character: a stylish young guy with a flat-brim cap, sunglasses, chain necklace and a full-face helmet under his arm. Action: posing confidently with two fingers up, one eyebrow raised, a small scooter behind him. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('moto', 'Moto', 'rua', 'veiculo', array['moto']::text[], 2, 2, 2, 3, 'Empina com o Mandrake.', 'Tanque cheio, farol aceso, sorriso no para-choque.', '[]'::jsonb, false, false, 'a small street scooter with a face on its headlight', 'doing a wheelie, front wheel high in the air, headlight eyes wide with joy, motion lines behind', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: traffic orange for the character, sky blue for the radiating sunburst. Character: a small street scooter with a face on its headlight. Action: doing a wheelie, front wheel high in the air, headlight eyes wide with joy, motion lines behind. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('vendedor-de-pamonha', 'Vendedor de Pamonha', 'rua', 'pessoa', '{}'::text[], 2, 1, 3, 6, 'Carro de som: no início de cada rodada, espia 1 carta da mão do oponente.', 'Olha a pamonha! Pamonha fresquinha! É o puro creme do milho!', '[{"trigger":"onRoundStart","name":"Carro de som","actions":[{"kind":"peekHand"}]}]'::jsonb, false, false, 'a cheerful street vendor next to an old car with a giant loudspeaker on the roof, holding corn husk bundles', 'shouting into the loudspeaker so loud that sound waves shake the whole scene, birds flying away', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: traffic orange for the character, sky blue for the radiating sunburst. Character: a cheerful street vendor next to an old car with a giant loudspeaker on the roof, holding corn husk bundles. Action: shouting into the loudspeaker so loud that sound waves shake the whole scene, birds flying away. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('saci', 'Saci', 'folclore', 'assombracao', '{}'::text[], 3, 2, 3, 5, 'À Noite: Redemoinho, troca de lugar duas cartas inimigas antes da briga.', 'Não levou nada. Só bagunçou tudo.', '[{"trigger":"beforeFight","name":"Redemoinho","conditions":[{"kind":"isNight"}],"actions":[{"kind":"swapEnemies","count":2}]}]'::jsonb, false, false, 'a one-legged mischievous boy with a red pointed cap and a small pipe, from Brazilian folklore', 'spinning inside a little whirlwind with a playful grin, leaves swirling around him', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: deep forest green for the character, fire orange for the full moon. Character: a one-legged mischievous boy with a red pointed cap and a small pipe, from Brazilian folklore. Action: spinning inside a little whirlwind with a playful grin, leaves swirling around him. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('curupira', 'Curupira', 'folclore', 'assombracao', '{}'::text[], 4, 3, 4, 3, 'À Noite: suas cartas brigam com a carteira diagonal (i+1). A da ponta bate direto na Moral.', 'Pode seguir as pegadas. Boa sorte.', '[{"trigger":"beforeFight","name":"Pés virados","conditions":[{"kind":"isNight"}],"actions":[{"kind":"diagonalFight"}]}]'::jsonb, false, false, 'a forest guardian boy with flaming orange hair and feet turned backwards', 'walking away while his footprints point the other way, winking at the viewer', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: deep forest green for the character, fire orange for the full moon. Character: a forest guardian boy with flaming orange hair and feet turned backwards. Action: walking away while his footprints point the other way, winking at the viewer. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('loira-do-banheiro', 'Loira do Banheiro', 'lendas', 'assombracao', '{}'::text[], 4, 4, 3, 2, 'Boato: se o oponente revelar 2 cartas e usar Tapa na mesma rodada, ela sai da sua mão e entra de graça numa carteira vazia.', 'Buuu! ...Ninguém? Tá bom, então.', '[{"trigger":"inHandOnReveal","name":"Boato","conditions":[{"kind":"opponentPlayedAndTapped","plays":2},{"kind":"hasEmptySlot"}],"actions":[{"kind":"enterFree"}]}]'::jsonb, false, false, 'a spooky but silly ghost girl with long pale hair and cotton in her nose, peeking out of a school bathroom stall', 'saying boo, then looking embarrassed because nobody got scared', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: violet for the character, acid lime for the puff of smoke cloud. Character: a spooky but silly ghost girl with long pale hair and cotton in her nose, peeking out of a school bathroom stall. Action: saying boo, then looking embarrassed because nobody got scared. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('homem-do-saco', 'Homem do Saco', 'lendas', 'assombracao', array['homem-saco']::text[], 3, 3, 4, 2, 'Com Mãe na fileira: "Olha que ele vem te pegar." Seus Filhos ganham +2 Resistência e o Homem do Saco não briga.', 'No saco só tem uma meia e uma borracha.', '[{"trigger":"static","name":"Olha que ele vem te pegar","conditions":[{"kind":"allyHasTag","tag":"mae"}],"actions":[{"kind":"buff","toughness":2,"target":{"tag":"filho","side":"ally"},"duration":"round"}]},{"trigger":"beforeFight","name":"Olha que ele vem te pegar","conditions":[{"kind":"allyHasTag","tag":"mae"}],"actions":[{"kind":"noFight","target":"self"}]}]'::jsonb, false, false, 'a tall lanky figure in a long coat carrying a big empty burlap sack', 'tiptoeing dramatically but the sack only contains a single sock and a lost school eraser', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: violet for the character, acid lime for the puff of smoke cloud. Character: a tall lanky figure in a long coat carrying a big empty burlap sack. Action: tiptoeing dramatically but the sack only contains a single sock and a lost school eraser. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('merendeira', 'Merendeira', 'escola', 'pessoa', array['cantina']::text[], 2, 1, 4, 2, 'Ao entrar, com Tia da Cantina na fileira: Repeteco, repete 1 efeito de entrada da sua fileira.', 'Hoje tem repeteco!', '[{"trigger":"onEnter","name":"Repeteco","conditions":[{"kind":"allyHasTag","tag":"cantina"}],"actions":[{"kind":"repeatEnterEffect"}]}]'::jsonb, false, false, 'a school lunch lady with hairnet and apron holding a giant ladle and a steaming pot', 'serving an impossibly tall pile of rice and beans with pride', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: ballpoint blue for the character, pencil yellow for the round chalkboard. Character: a school lunch lady with hairnet and apron holding a giant ladle and a steaming pot. Action: serving an impossibly tall pile of rice and beans with pride. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
  ('tia-da-cantina', 'Tia da Cantina', 'escola', 'pessoa', array['cantina']::text[], 2, 1, 3, 2, 'Ativa o Repeteco da Merendeira.', 'Fiado só amanhã.', '[]'::jsonb, false, false, 'a friendly school snack bar lady behind a small counter full of snacks, pencil behind her ear', 'handing a warm cheese bread to a tiny hand reaching up, while writing on a notebook with the other hand', 'Match the exact style of the reference image. Brazilian cordel woodcut illustration printed as a two-color risograph, sticker style. Bold hand-carved black outlines with rough gouge marks, flat ink fills, visible halftone dots, slight misregistration between color layers, grainy cream paper texture. Single full-body cartoon character centered, big head, oversized hands and feet, exaggerated funny expression. Thick off-white die-cut sticker border around the character. One simple background shape behind the character, plain paper elsewhere. Vertical 4:5 composition with margin around the sticker. Inks: ballpoint blue for the character, pencil yellow for the round chalkboard. Character: a friendly school snack bar lady behind a small counter full of snacks, pencil behind her ear. Action: handing a warm cheese bread to a tiny hand reaching up, while writing on a notebook with the other hand. Only black plus the two inks listed, no other colors. No text, no letters, no numbers, no logos, no brand names, no real people, no weapons, no blood, no gradients, no glossy highlights, no 3D render, no photorealism.'),
